<span class="line"><span class="token keyword">assert</span> request2<span class="token punctuation">(</span><span class="token number">61184</span><span class="token punctuation">,</span> <span class="token boolean">False</span><span class="token punctuation">,</span> ext<span class="token operator">=</span><span class="token number">0x12</span><span class="token punctuation">,</span> ext_len<span class="token operator">=</span><span class="token number">1</span><span class="token punctuation">)</span> <span class="token operator">==</span> <span class="token punctuation">[</span><span class="token number">0x00</span><span class="token punctuation">,</span> <span class="token number">0xEF</span><span class="token punctuation">,</span> <span class="token number">0x00</span><span class="token punctuation">,</span> <span class="token number">0xE4</span><span class="token punctuation">,</span> <span class="token number">0x12</span><span class="token punctuation">,</span> <span class="token number">0xFF</span><span class="token punctuation">,</span> <span class="token number">0xFF</span><span class="token punctuation">,</span> <span class="token number">0xFF</span><span class="token punctuation">]</span></span>
